package net.civeira.phylax.feature.access.apikeyclient.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.access.apikeyclient.domain.ApiKeyClient;
import net.civeira.phylax.feature.access.apikeyclient.domain.valueobject.ScopesVO;

class ScopesValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of scopes of api key client")
  void test_scopes_value_holder_assign_plain_value() {
    Object holder = new Object();
    ScopesValueHolder<Object> value = new ScopesValueHolder<>(holder);
    Assertions.assertSame(holder, value.scopes("one"), "Setters must return the holder");
    Assertions.assertTrue(value.getScopesValue().isPresent(), "The plain value must be stored");
    Assertions.assertEquals("one", value.getScopes().orElse(null),
        "The plain value must be recovered");
    Assertions.assertSame(holder, value.scopesNull(), "Setters must return the holder");
    Assertions.assertTrue(value.getScopesValue().isPresent(), "A null value object must be stored");
    Assertions.assertFalse(value.getScopes().isPresent(), "A null value must not have content");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of scopes of api key client")
  void test_scopes_value_holder_assign_value_object() {
    Object holder = new Object();
    ScopesValueHolder<Object> value = new ScopesValueHolder<>(holder);
    ScopesVO vo = ScopesVO.from("one");
    Assertions.assertFalse(value.getScopesValue().isPresent(), "A new holder must be empty");
    Assertions.assertSame(holder, value.scopes(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getScopesValue().orElseThrow());
    Assertions.assertSame(holder, value.scopes(Optional.empty()));
    Assertions.assertFalse(value.getScopesValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.scopes(Optional.of(vo)));
    Assertions.assertSame(vo, value.getScopesValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of scopes of api key client against the original")
  void test_scopes_value_holder_read() {
    Object holder = new Object();
    ScopesValueHolder<Object> value = new ScopesValueHolder<>(holder);
    ScopesVO vo = ScopesVO.from("one");
    ScopesVO other = ScopesVO.from("one");
    ApiKeyClient original = Mockito.mock(ApiKeyClient.class);
    Mockito.when(original.getScopesValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readScopes(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNotNull(value.readScopes(Optional.empty(), fails),
        "Without value and original a null value is returned");
    Assertions.assertTrue(fails.isEmpty(), "An optional value is never reported as missing");
    value.scopes(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readScopes(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readScopes(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of scopes of api key client")
  void test_scopes_value_holder_unset() {
    Object holder = new Object();
    ScopesValueHolder<Object> value = new ScopesValueHolder<>(holder);
    ScopesVO vo = ScopesVO.from("one");
    value.scopes(vo);
    Assertions.assertSame(holder, value.unsetScopesIfMatches("scopes_other"));
    Assertions.assertTrue(value.getScopesValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetScopesIfMatches("scopes"));
    Assertions.assertFalse(value.getScopesValue().isPresent(),
        "The field name must clear the value");
    value.scopes(vo);
    Assertions.assertSame(holder, value.unsetScopes());
    Assertions.assertFalse(value.getScopesValue().isPresent(), "Unset must clear the value");
  }
}
